package com.aitzaz.a32doctor;
import android.app.*; import android.os.*; import android.graphics.*; import android.view.*; import android.widget.*;
public class TouchTestActivity extends Activity { TextView info; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(20,20,20,20); info=new TextView(this);info.setText("Touch / Ghost-Touch Test\n\nDisconnect charger and touch the screen normally. Then connect the charger and repeat.\nUnexpected touches without touching the screen can indicate charger/cable/electrical interference or a digitizer issue.");info.setTextSize(18); l.addView(info); setContentView(l);}
 public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN) info.setText("Touch detected at X="+(int)e.getX()+" Y="+(int)e.getY()+"\n\nRepeat with charger connected. If touches appear by themselves, stop using that charger/cable."); return super.dispatchTouchEvent(e);}}
